	/**
	 * Patogumo metodas: surenka viska i viena eilute.
	 */
	public static function wrap( $args ) {
		$a = wp_parse_args( $args, array(
			'subject'    => '',
			'preheader'  => '',
			'body'       => '',
			'flow_class' => 'service',
			'email'      => '',
			'reason'     => '',
		) );
		return self::open( $a['subject'], $a['preheader'] )
			. $a['body']
			. self::close( $a['flow_class'], $a['email'], $a['reason'] );
	}
